protected void onPostExecute(Bitmap bitmap){
  if (bitmap != null) {
    try {
      AvatarGenerationListener listener = mAvatarGenerationListener.get();
      AvatarGenerationTask avatarWorkerTask = getAvatarWorkerTask(mCallContext);
      if (this == avatarWorkerTask && listener != null && listener.shouldCallGeneratedCallback(mUsername, mCallContext)) {
        listener.avatarGenerated(new BitmapDrawable(bitmap), mCallContext);
      }
    } catch (RuntimeException e) {
      // 处理运行时异常，如NullPointerException或BitmapDrawable构造异常
      Log.e("AvatarGeneration", "Error generating avatar", e);
    }
  }
}
